        return (0, 0)

    error = bearing_to(enemy.x, enemy.y)
    distance = distance_to(enemy.x, enemy.y)

    # Positive steering turns right wheels faster, increasing heading.
    # The feed-forward term opposes the horizontal rotor's reaction.
    steer = 0.025 * error - 0.015 * me.turn_rate + 0.05
    if steer > 0.6:
        steer = 0.6
    elif steer < -0.6:
        steer = -0.6

    if distance > 3.0:
        base = 0.58
    elif distance > 1.5:
        base = 0.52
    else:
        base = 0.44

    left = base - steer
    right = base + steer

    if left > 1.0:
        left = 1.0
    elif left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    elif right < -1.0:
        right = -1.0

    return (left, right)


