def drive(me, enemy, arena):
    # bearing to enemy (degrees, positive to left)
    bearing = bearing_to(enemy.x, enemy.y)
    # distance to enemy
    dist = distance_to(enemy.x, enemy.y)

    # if we are far, drive straight toward enemy
    if dist > 2.5:
        # turn to face enemy
        if bearing > 15:
            return (-0.7, 0.7)   # turn left
        elif bearing < -15:
            return (0.7, -0.7)   # turn right
        else:
            return (0.9, 0.9)    # full forward
    # close range: keep facing, moderate speed
    if bearing > 10:
        return (-0.5, 0.5)
    elif bearing < -10:
        return (0.5, -0.5)
    else:
        return (0.6, 0.6)


