def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)

    weapon = me.weapons.get("front")
    distance = distance_to(enemy.x, enemy.y)

    if weapon is not None and weapon.get("holding", False):
        radial = sqrt(enemy.x * enemy.x + enemy.y * enemy.y)
        if radial > 0.1:
            target_x = enemy.x + enemy.x / radial * 2.0
            target_y = enemy.y + enemy.y / radial * 2.0
        else:
            target_x = arena.radius
            target_y = 0.0

        error = bearing_to(target_x, target_y)
        steer = 0.035 * error - 0.015 * me.turn_rate
        base = 0.60
        limit = 0.45
    else:
        lead = min(0.35, distance * 0.15)
        target_x = enemy.x + enemy.vx * lead
        target_y = enemy.y + enemy.vy * lead

        error = bearing_to(target_x, target_y)
        steer = 0.045 * error - 0.020 * me.turn_rate

        if distance > 4.0:
            base = 0.72
        elif distance > 2.0:
            base = 0.64
        else:
            base = 0.55
        limit = 0.75

    if steer > limit:
        steer = limit
    elif steer < -limit:
        steer = -limit

    left = base - steer
    right = base + steer

    if left > 1.0:
        left = 1.0
    elif left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    elif right < -1.0:
        right = -1.0

    return (left, right)


def weapons(me, enemy, arena):
    weapon = me.weapons.get("front")
    if weapon is None:
        return None

    if weapon.get("holding", False):
        me.memory["grabbing"] = True
        return None

    if weapon.get("state") == "closed":
        me.memory["grabbing"] = False
        return release("front")

    if me.memory.get("grabbing", False):
        return None

    if distance_to(enemy.x, enemy.y) < 2.2:
        me.memory["grabbing"] = True
        return grab("front")

    return None

def drive(me, enemy, arena):
    # bearing to enemy (degrees, positive to left)
    bearing = bearing_to(enemy.x, enemy.y)
    dist = distance_to(enemy.x, enemy.y)

    # proportional turn to keep front facing enemy
    turn = -bearing * 0.02          # tune factor
    if turn > 1:
        turn = 1
    elif turn < -1:
        turn = -1

    # forward speed: faster when far, slower when close
    base = 0.85 if dist > 2.0 else 0.55

    left = base + turn
    right = base - turn

    # clamp throttles
    if left > 1:
        left = 1
    elif left < -1:
        left = -1
    if right > 1:
        right = 1
    elif right < -1:
        right = -1

    return (left, right)


